REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (NULL, 'prom_yml_tmpl', '{\r\n    \"global\": {\r\n        \"scrape_interval\": \"${scrape_interval}s\",\r\n        \"scrape_timeout\": 	<#if scrape_timeout??> \r\n								\"${scrape_timeout}s\",\r\n						    <#else>\r\n								\"10s\",\r\n							</#if>\r\n        \"evaluation_interval\": \"${scrape_interval}s\"\r\n    },\r\n	\r\n	<#-- alert 配置 -->\r\n	<#if isAlert>\r\n	\"alerting\": {\r\n		\"alertmanagers\": [{\r\n			\"path_prefix\": \"${path_prefix}\",\r\n			\"static_configs\": [{\r\n				\"targets\": [\"${alert_url}\"]\r\n			}]\r\n		}],\r\n		\"alert_relabel_configs\": [{\r\n			\"regex\": \"instance\",\r\n			\"action\": \"labeldrop\"\r\n		}, {\r\n			\"regex\": \"replica\",\r\n			\"action\": \"labeldrop\"\r\n		}]\r\n	},\r\n	\"rule_files\": [\"rule.yml\"],\r\n	</#if>\r\n	\r\n	\r\n	\r\n	<#-- per-datacenter 配置 -->\r\n	<#if !isGlobal>\r\n    \"scrape_configs\": [\r\n	<#list jobList as jobPojo>\r\n			{\r\n				\"job_name\": \"${jobPojo.job_name}\",\r\n				\"scheme\": \"${jobPojo.scheme?default(\"http\")}\",\r\n				\"tls_config\":{\r\n					\"insecure_skip_verify\": true\r\n				},\r\n				\"metrics_path\": <#if jobPojo.metrics_path?default(\"\")?trim?length gt 0>\r\n									\"${jobPojo.metrics_path}\",\r\n								<#else>\r\n									\"/metrics\",\r\n								</#if>\r\n				\"static_configs\":[\r\n					<#list jobPojo.staticConfigList as staticConf >\r\n						{\r\n						  \"targets\": [\r\n								<#list staticConf.targets as targetConf>\r\n										\"${targetConf}\"<#sep>,</#sep>\r\n								</#list>\r\n							]\r\n						<#if staticConf.labels ??&& (staticConf.labels?size >0)>\r\n						   ,\r\n						   \"labels\": {\r\n								<#list staticConf.labels?keys as itemKey>\r\n									\"${itemKey}\":<#if staticConf.labels[itemKey]?default(\"\")?trim?length gt 0>\r\n													\"${staticConf.labels[itemKey]}\"\r\n												  <#else>\"\"</#if><#sep>,</#sep>\r\n								</#list>\r\n							} \r\n						</#if>\r\n						}<#sep>,</#sep>\r\n					</#list>\r\n					],\r\n				\"relabel_configs\": [\r\n					{\r\n						\"regex\": \"job\",\r\n						\"action\": \"labeldrop\"\r\n					}\r\n					<#if !jobPojo.instanceRelabel> \r\n					,\r\n					{\r\n						\"regex\": \"instance\",\r\n						\"action\": \"labeldrop\"\r\n					}\r\n					</#if>\r\n				],\r\n				\"metric_relabel_configs\": [\r\n					{\r\n						\"regex\": \"job\",\r\n						\"action\": \"labeldrop\"\r\n					}\r\n					<#if !jobPojo.instanceRelabel> \r\n					,\r\n					{\r\n						\"regex\": \"instance\",\r\n						\"action\": \"labeldrop\"\r\n					}\r\n					</#if>\r\n				]\r\n			}<#sep>,</#sep>\r\n		</#list>\r\n		<#if jobList??&&(jobList?size>0)>\r\n		,\r\n		</#if>\r\n		<#list endpointList as endpoint>\r\n			{\r\n				\"job_name\": ${endpoint.id?c},\r\n				\"tls_config\":{\r\n					\"insecure_skip_verify\": true\r\n				},\r\n				\"metrics_path\": <#if endpoint.config.metrics_path?default(\"\")?trim?length gt 0>\r\n									\"${endpoint.config.metrics_path}\",\r\n								<#else>\r\n									<#if endpoint.config.protocol == \"http\" || endpoint.config.protocol == \"https\">\r\n										\"/metrics\",\r\n									<#else>\r\n										\"/snmp\",\r\n									</#if>\r\n								</#if>\r\n				\"scrape_interval\": 	<#if endpoint.config.scrape_interval?default(\"\")?trim?length gt 0>\r\n										\"${endpoint.config.scrape_interval}s\",\r\n									<#else>\r\n										\"${scrape_interval}s\",\r\n									</#if>\r\n				\"scrape_timeout\": 	<#if endpoint.config.scrape_timeout?default(\"\")?trim?length gt 0>\r\n										\"${endpoint.config.scrape_timeout}s\",\r\n									<#else>\r\n										<#if scrape_timeout??> \r\n											\"${scrape_timeout}s\",\r\n										<#else>\r\n											\"10s\",\r\n										</#if>\r\n									</#if>\r\n\r\n\r\n\r\n				<#if endpoint.config.basic_auth??&& (endpoint.config.basic_auth?size >0)>\r\n					<#if endpoint.config.basic_auth.username?default(\"\")?trim?length gt 0 && endpoint.config.basic_auth.password?default(\"\")?trim?length gt 0>\r\n					\"basic_auth\":{\r\n						\"username\": \"${endpoint.config.basic_auth.username}\",\r\n						\"password\": \"${endpoint.config.basic_auth.password}\"\r\n						},\r\n					</#if>\r\n				</#if>\r\n				\r\n				<#if endpoint.config.bearer_token??&&endpoint.config.bearer_token?trim?length gt 0>\r\n					\"authorization\":{\r\n						\"type\":\"Bearer\",\r\n						\"credentials\":\"${endpoint.config.bearer_token}\"\r\n					},\r\n				</#if>\r\n\r\n				\r\n				<#-- params 不为空且类型为 http ，添加 params -->\r\n				<#if endpoint.config.protocol == \"http\" || endpoint.config.protocol == \"https\" >\r\n					\"scheme\": \"${endpoint.config.protocol}\",\r\n					<#if endpoint.config.params?? && (endpoint.config.params?size >0) >\r\n						\"params\":{\r\n							<#list endpoint.config.params?keys as itemKey>\r\n							\"${itemKey}\":[\r\n								<#list endpoint.config.params[itemKey] as pojo>\r\n									\"${pojo}\"\r\n									<#sep>,</#sep>\r\n								</#list>\r\n								]\r\n								<#sep>,</#sep>\r\n							</#list>\r\n						},\r\n					</#if>\r\n				<#elseif endpoint.config.protocol == \"snmp\">\r\n				<#-- 类型是 snmp ，组织 param 数据 ， 原来params弃用，因为 snmp_exporter 不支持其他参数 -->\r\n				   \"params\":{\r\n						\"target\":[ \"${endpoint.config.host}:${endpoint.config.port?c}\" ],\r\n						\"module\":[ \"${endpoint.module.name}\" ]\r\n					},\r\n				</#if>\r\n				\r\n				\"static_configs\": [{\r\n					\"targets\": [<#if endpoint.config.protocol == \"http\" || endpoint.config.protocol == \"https\">\r\n									\"${endpoint.config.host}:${endpoint.config.port?c}\"\r\n								<#else>\r\n									\"127.0.0.1:19116\"\r\n								</#if>\r\n								],\r\n					\"labels\": {\r\n						\"datacenter\": 	\"${endpoint.dc.name}\",\r\n                        \"datacenter_id\":${endpoint.dc.id?c},\r\n						\r\n						\"project\": 		\"${endpoint.project.name}\",\r\n						\"project_id\":   ${endpoint.project.id?c},\r\n						\r\n						\"asset\": 		\"${endpoint.asset.name}\",\r\n						\"asset_id\":     ${endpoint.asset.id?c},\r\n						\r\n						\"module\": 		\"${endpoint.module.name}\",\r\n						\"module_id\":    ${endpoint.module.id?c},\r\n						\r\n						\"endpoint\":     \"${endpoint.name}\",\r\n						\"endpoint_id\":  ${endpoint.id?c},\r\n						\r\n						<#if endpoint.asset.parent??&&(endpoint.asset.parent?size >0)>\r\n							\"parent_asset\"      :  \"${endpoint.asset.parent.name}\",\r\n							\"parent_asset_id\"   :   ${endpoint.asset.parent.id?c},\r\n						</#if>\r\n\r\n						\"nz_agent_id\":  ${endpoint.promserver.id?c}\r\n												\r\n										\r\n										<#if endpoint.config.labels??&& (endpoint.config.labels?size >0)>\r\n											,\r\n										</#if>\r\n										<#-- 补充用户自定义 Labels -->\r\n										<#if endpoint.config.labels??&& (endpoint.config.labels?size >0)>\r\n											<#list endpoint.config.labels?keys as key>\r\n												<#if key != \"datacenter\" && key != \"datacenter_id\" && key != \"project\" && key != \"project_id\" && key != \"asset\" && key != \"asset_id\" && key != \"module\" && key != \"module_id\" && key != \"endpoint\" && key != \"endpoint_id\">\r\n													\"${key}\":\"${endpoint.config.labels[key]}\"<#sep>,</#sep>\r\n												</#if>\r\n											 </#list>\r\n										</#if>\r\n					}\r\n				}],\r\n				\"metric_relabel_configs\": [\r\n					{\r\n						\"regex\": \"job\",\r\n						\"action\": \"labeldrop\"\r\n					},\r\n					{\r\n						\"regex\": \"instance\",\r\n						\"action\": \"labeldrop\"\r\n					}\r\n					<#if endpoint.config.relabel_config??&& (endpoint.config.relabel_config?size >0)>\r\n						<#list endpoint.config.relabel_config as relabel>\r\n							,{\r\n								<#if relabel.action?? && (relabel.action == \'labeldrop\' || relabel.action == \'labelkeep\')>\r\n									\"regex\": \"${(relabel.regex)!\'\'}\",\r\n									\"action\": \"${(relabel.action)!\'\'}\"\r\n								</#if>\r\n								<#if relabel.action?? && relabel.action == \'labelmap\'>\r\n									\"regex\": \"${(relabel.regex)!\'\'}\",\r\n									\"action\": \"${(relabel.action)!\'\'}\",\r\n									\"replacement\": \"${(relabel.replacement)!\'\'}\"\r\n								</#if>\r\n								<#if relabel.action?? && (relabel.action == \'drop\' || relabel.action == \'keep\')>\r\n									<#if relabel.source_labels??&& (relabel.source_labels?size >0)>\r\n										\"source_labels\":[\r\n											<#list relabel.source_labels as label>\r\n												\"${label!\'\'}\"<#sep>,</#sep>\r\n											</#list>\r\n										],\r\n									</#if>\r\n									\"regex\": \"${(relabel.regex)!\'\'}\",\r\n									\"action\": \"${(relabel.action)!\'\'}\"\r\n								</#if>\r\n								<#if relabel.action?? && relabel.action == \'replace\'>\r\n									<#if relabel.source_labels??&& (relabel.source_labels?size >0)>\r\n										\"source_labels\":[\r\n											<#list relabel.source_labels as label>\r\n												\"${label!\'\'}\"<#sep>,</#sep>\r\n											</#list>\r\n										],\r\n									</#if>\r\n									\"separator\": \";\",\r\n									\"regex\": \"${(relabel.regex)!\'\'}\",\r\n									\"replacement\": \"${(relabel.replacement)!\'\'}\",\r\n									\"action\": \"${(relabel.action)!\'\'}\",\r\n									\"target_label\": \"${(relabel.target_label)!\'\'}\"\r\n								</#if>\r\n							}\r\n						</#list>\r\n					</#if>\r\n				]\r\n			}\r\n			<#sep>,</#sep>\r\n		</#list>\r\n		\r\n		<#-- ping 配置 -->\r\n		\r\n		<#if endpointList??&&(endpointList?size>0)>\r\n		,\r\n		</#if>\r\n		\r\n		<#list assetList as asset>\r\n		{\r\n			\"job_name\": 	\"asset_ping_${asset.id?c}\",\r\n			\"tls_config\":{\r\n				\"insecure_skip_verify\": true\r\n			},\r\n			\"metrics_path\": \"/probe\",\r\n			\"scrape_interval\": 	<#if asset.assetPingInterval?default(\"\")?trim?length gt 0>\r\n									\"${asset.assetPingInterval}s\",\r\n								<#else>\r\n									\"${scrape_interval}s\",\r\n								</#if>\r\n			\"scrape_timeout\": 	<#if asset.scrape_timeout?default(\"\")?trim?length gt 0>\r\n									\"${asset.scrape_timeout}s\",\r\n								<#else>\r\n									<#if scrape_timeout??> \r\n										\"${scrape_timeout}s\",\r\n									<#else>\r\n										\"10s\",\r\n									</#if>\r\n								</#if>\r\n            \"params\":	{\r\n				\"target\":[ \"${asset.manageIp}\" ],\r\n				\"module\":[ \"ping\" ]\r\n			},\r\n			\"static_configs\": [{\r\n				\"targets\": [\"127.0.0.1:19115\"],\r\n				\"labels\": {\r\n					\"datacenter\": 	\"${asset.dc.name}\",\r\n					\"host\": 	  	\"${asset.manageIp}\",\r\n					\"module\":       \"ping\",\r\n					\"source_ip\":    \"${asset.promserver.host}\",\r\n					\"nz_agent_id\":  ${asset.promserver.id?c}\r\n				}\r\n			}],\r\n			\"relabel_configs\": [\r\n				{\r\n					\"regex\": \"job\",\r\n					\"action\": \"labeldrop\"\r\n				},\r\n				{\r\n					\"regex\": \"instance\",\r\n					\"action\": \"labeldrop\"\r\n				}\r\n			],\r\n			\"metric_relabel_configs\": [\r\n			    {\r\n					\"regex\": \"job\",\r\n					\"action\": \"labeldrop\"\r\n				},\r\n				{\r\n					\"regex\": \"instance\",\r\n					\"action\": \"labeldrop\"\r\n				}\r\n			]\r\n		}\r\n		<#sep>,</#sep>\r\n		</#list>\r\n    ]\r\n	<#-- cortex 处理 -->\r\n	,\r\n	\"remote_write\": [\r\n		<#list remoteWriteUrlInfos as remoteConf>\r\n		{\r\n			\"url\": \"${remoteConf.url}\",\r\n			\"authorization\": {\r\n				\"type\": \"Bearer\",\r\n				\"credentials\": \"${remoteConf.token}\"\r\n			},\r\n			\"tls_config\":{\r\n				\"insecure_skip_verify\":true\r\n			},\r\n			\"queue_config\":{\r\n				\"capacity\": 5000,\r\n			    \"max_samples_per_send\": 1000,\r\n				\"min_shards\": 5,\r\n				\"max_shards\": 10,\r\n				\"min_backoff\": \"20ms\",\r\n				\"min_backoff\": \"50ms\"\r\n			}\r\n		}\r\n		<#sep>,</#sep>\r\n		</#list>\r\n	]\r\n	<#else>\r\n	<#-- global 配置 -->\r\n	\"scrape_configs\": [\r\n		<#list jobList as jobPojo>\r\n			{\r\n			   \"job_name\": \"${jobPojo.job_name}\",\r\n			   \"scheme\": \"${jobPojo.scheme?default(\"http\")}\",\r\n			   \"tls_config\":{\r\n					\"insecure_skip_verify\": true\r\n				},\r\n				<#if jobPojo.isFederate> \r\n				\"honor_labels\": ${jobPojo.honor_labels},\r\n				\"params\": {\r\n					\"match[]\": [\r\n						\"{__name__=~\\\".+\\\",nz_agent_id != \\\"${jobPojo.excludeAgentId}\\\"}\"\r\n					]\r\n				},\r\n				\"authorization\":{\r\n					\"type\":\"Bearer\",\r\n					\"credentials\":\"${jobPojo.token}\"\r\n				},\r\n				</#if>\r\n				\"metrics_path\": <#if jobPojo.metrics_path?default(\"\")?trim?length gt 0>\r\n									\"${jobPojo.metrics_path}\",\r\n								<#else>\r\n									\"/metrics\",\r\n								</#if>\r\n				\"static_configs\":[\r\n					<#list jobPojo.staticConfigList as staticConf >\r\n						{\r\n						  \"targets\": [\r\n								<#list staticConf.targets as targetConf>\r\n										\"${targetConf}\"<#sep>,</#sep>\r\n								</#list>\r\n							]\r\n						<#if staticConf.labels ??&& (staticConf.labels?size >0)>\r\n						   ,\r\n						   \"labels\": {\r\n								<#list staticConf.labels?keys as itemKey>\r\n									\"${itemKey}\":<#if staticConf.labels[itemKey]?default(\"\")?trim?length gt 0>\r\n													\"${staticConf.labels[itemKey]}\"\r\n												  <#else>\"\"</#if><#sep>,</#sep>\r\n								</#list>\r\n							} \r\n						</#if>\r\n						}<#sep>,</#sep>\r\n					</#list>\r\n					],\r\n				\"relabel_configs\": [\r\n					{\r\n						\"regex\": \"job\",\r\n						\"action\": \"labeldrop\"\r\n					}\r\n					<#if !jobPojo.instanceRelabel> \r\n					,\r\n					{\r\n						\"regex\": \"instance\",\r\n						\"action\": \"labeldrop\"\r\n					}\r\n					</#if>\r\n				],\r\n				\"metric_relabel_configs\": [\r\n					{\r\n						\"regex\": \"job\",\r\n						\"action\": \"labeldrop\"\r\n					}\r\n					<#if !jobPojo.instanceRelabel> \r\n					,\r\n					{\r\n						\"regex\": \"instance\",\r\n						\"action\": \"labeldrop\"\r\n					}\r\n					</#if>\r\n				]\r\n			}<#sep>,</#sep>\r\n		</#list>\r\n		\r\n		<#-- ping 配置 -->\r\n		\r\n		<#if jobList??&&(jobList?size>0)>\r\n		,\r\n		</#if>\r\n		\r\n		<#list assetList as asset>\r\n		{\r\n			\"job_name\": 	\"asset_ping_${asset.id?c}\",\r\n			\"tls_config\":{\r\n				\"insecure_skip_verify\": true\r\n			},\r\n			\"metrics_path\": \"/probe\",\r\n			\"scrape_interval\": 	<#if asset.assetPingInterval?default(\"\")?trim?length gt 0>\r\n									\"${asset.assetPingInterval}s\",\r\n								<#else>\r\n									\"${scrape_interval}s\",\r\n								</#if>\r\n			\"scrape_timeout\": 	<#if asset.scrape_timeout?default(\"\")?trim?length gt 0>\r\n									\"${asset.scrape_timeout}s\",\r\n								<#else>\r\n									<#if scrape_timeout??> \r\n										\"${scrape_timeout}s\",\r\n									<#else>\r\n										\"10s\",\r\n									</#if>\r\n								</#if>\r\n            \"params\":	{\r\n				\"target\":[ \"${asset.manageIp}\" ],\r\n				\"module\":[ \"ping\" ]\r\n			},\r\n			\"static_configs\": [{\r\n				\"targets\": [\"127.0.0.1:19115\"],\r\n				\"labels\": {\r\n					\"datacenter\": 	\"${asset.dc.name}\",\r\n					\"host\": 	  	\"${asset.manageIp}\",\r\n					\"module\":       \"ping\",\r\n					\"source_ip\":    \"${asset.promserver.host}\",\r\n					\"nz_agent_id\":  ${asset.promserver.id?c}\r\n				}\r\n			}],\r\n			\"relabel_configs\": [\r\n				{\r\n					\"regex\": \"job\",\r\n					\"action\": \"labeldrop\"\r\n				},\r\n				{\r\n					\"regex\": \"instance\",\r\n					\"action\": \"labeldrop\"\r\n				}\r\n			],\r\n			\"metric_relabel_configs\": [\r\n			    {\r\n					\"regex\": \"job\",\r\n					\"action\": \"labeldrop\"\r\n				},\r\n				{\r\n					\"regex\": \"instance\",\r\n					\"action\": \"labeldrop\"\r\n				}\r\n			]\r\n		}\r\n		<#sep>,</#sep>\r\n		</#list>\r\n		\r\n		\r\n		<#if ( jobList??&&(jobList?size>0)) ||  assetList??&&(assetList?size>0)>\r\n		,\r\n		</#if>\r\n		\r\n		<#list endpointList as endpoint>\r\n			{\r\n				\"job_name\": ${endpoint.id?c},\r\n				\"tls_config\":{\r\n					\"insecure_skip_verify\": true\r\n				},\r\n				\"metrics_path\": <#if endpoint.config.metrics_path?default(\"\")?trim?length gt 0>\r\n									\"${endpoint.config.metrics_path}\",\r\n								<#else>\r\n									\"/metrics\",\r\n								</#if>\r\n				\"scrape_interval\": 	<#if endpoint.config.scrape_interval?default(\"\")?trim?length gt 0>\r\n										\"${endpoint.config.scrape_interval}s\",\r\n									<#else>\r\n										\"${scrape_interval}s\",\r\n									</#if>\r\n				\"scrape_timeout\": 	<#if endpoint.config.scrape_timeout?default(\"\")?trim?length gt 0>\r\n										\"${endpoint.config.scrape_timeout}s\",\r\n									<#else>\r\n										<#if scrape_timeout??> \r\n											\"${scrape_timeout}s\",\r\n										<#else>\r\n											\"10s\",\r\n										</#if>\r\n									</#if>\r\n\r\n\r\n\r\n				<#if endpoint.config.basic_auth??&& (endpoint.config.basic_auth?size >0)>\r\n					<#if endpoint.config.basic_auth.username?default(\"\")?trim?length gt 0 && endpoint.config.basic_auth.password?default(\"\")?trim?length gt 0>\r\n					\"basic_auth\":{\r\n						\"username\": \"${endpoint.config.basic_auth.username}\",\r\n						\"password\": \"${endpoint.config.basic_auth.password}\"\r\n						},\r\n					</#if>\r\n				</#if>\r\n				\r\n				\r\n				<#if endpoint.config.bearer_token??&&endpoint.config.bearer_token?trim?length gt 0>\r\n					\"authorization\":{\r\n						\"type\":\"Bearer\",\r\n						\"credentials\":\"${endpoint.config.bearer_token}\"\r\n					},\r\n				</#if>\r\n\r\n				\r\n				<#-- params 不为空且类型为 http ，添加 params -->\r\n				<#if endpoint.config.protocol == \"http\" || endpoint.config.protocol == \"https\" >\r\n					\"scheme\": \"${endpoint.config.protocol}\",\r\n					<#if endpoint.config.params?? && (endpoint.config.params?size >0) >\r\n						\"params\":{\r\n							<#list endpoint.config.params?keys as itemKey>\r\n							\"${itemKey}\":[\r\n								<#list endpoint.config.params[itemKey] as pojo>\r\n									\"${pojo}\"\r\n									<#sep>,</#sep>\r\n								</#list>\r\n								]\r\n								<#sep>,</#sep>\r\n							</#list>\r\n						},\r\n					</#if>\r\n				<#elseif endpoint.config.protocol == \"snmp\">\r\n				<#-- 类型是 snmp ，组织 param 数据 ， 原来params弃用，因为 snmp_exporter 不支持其他参数 -->\r\n				   \"params\":{\r\n						\"target\":[ \"${endpoint.config.host}:${endpoint.config.port?c}\" ],\r\n						\"module\":[ \"${endpoint.module.name}\" ]\r\n					},\r\n				</#if>\r\n				\r\n				\"static_configs\": [{\r\n					\"targets\": [<#if endpoint.config.protocol == \"http\" || endpoint.config.protocol == \"https\">\r\n									\"${endpoint.config.host}:${endpoint.config.port?c}\"\r\n								<#else>\r\n									\"127.0.0.1:19116\"\r\n								</#if>\r\n								],\r\n					\"labels\": {\r\n						\"datacenter\": 	\"${endpoint.dc.name}\",\r\n                        \"datacenter_id\":${endpoint.dc.id?c},\r\n						\r\n						\"project\": 		\"${endpoint.project.name}\",\r\n						\"project_id\":   ${endpoint.project.id?c},\r\n						\r\n						\"asset\": 		\"${endpoint.asset.name}\",\r\n						\"asset_id\":     ${endpoint.asset.id?c},\r\n						\r\n						\"module\": 		\"${endpoint.module.name}\",\r\n						\"module_id\":    ${endpoint.module.id?c},\r\n						\r\n						\"endpoint\":     \"${endpoint.name}\",\r\n						\"endpoint_id\":  ${endpoint.id?c},\r\n						\r\n						<#if endpoint.asset.parent??&&(endpoint.asset.parent?size >0)>\r\n							\"parent_asset\"      :  \"${endpoint.asset.parent.name}\",\r\n							\"parent_asset_id\"   :   ${endpoint.asset.parent.id?c},\r\n						</#if>\r\n						\r\n						\"nz_agent_id\":  ${endpoint.promserver.id?c}\r\n												\r\n										\r\n										<#if endpoint.config.labels??&& (endpoint.config.labels?size >0)>\r\n											,\r\n										</#if>\r\n										<#-- 补充用户自定义 Labels -->\r\n										<#if endpoint.config.labels??&& (endpoint.config.labels?size >0)>\r\n											<#list endpoint.config.labels?keys as key>\r\n												<#if key != \"datacenter\" && key != \"datacenter_id\" && key != \"project\" && key != \"project_id\" && key != \"asset\" && key != \"asset_id\" && key != \"module\" && key != \"module_id\" && key != \"endpoint\" && key != \"endpoint_id\">\r\n													\"${key}\":\"${endpoint.config.labels[key]}\"<#sep>,</#sep>\r\n												</#if>\r\n											 </#list>\r\n										</#if>\r\n					}\r\n				}],\r\n				\"metric_relabel_configs\": [\r\n					{\r\n						\"regex\": \"job\",\r\n						\"action\": \"labeldrop\"\r\n					},\r\n					{\r\n						\"regex\": \"instance\",\r\n						\"action\": \"labeldrop\"\r\n					}\r\n					<#if endpoint.config.relabel_config??&& (endpoint.config.relabel_config?size >0)>\r\n						<#list endpoint.config.relabel_config as relabel>\r\n							,{\r\n								<#if relabel.action?? && (relabel.action == \'labeldrop\' || relabel.action == \'labelkeep\')>\r\n									\"regex\": \"${(relabel.regex)!\'\'}\",\r\n									\"action\": \"${(relabel.action)!\'\'}\"\r\n								</#if>\r\n								<#if relabel.action?? && relabel.action == \'labelmap\'>\r\n									\"regex\": \"${(relabel.regex)!\'\'}\",\r\n									\"action\": \"${(relabel.action)!\'\'}\",\r\n									\"replacement\": \"${(relabel.replacement)!\'\'}\"\r\n								</#if>\r\n								<#if relabel.action?? && (relabel.action == \'drop\' || relabel.action == \'keep\')>\r\n									<#if relabel.source_labels??&& (relabel.source_labels?size >0)>\r\n										\"source_labels\":[\r\n											<#list relabel.source_labels as label>\r\n												\"${label!\'\'}\"<#sep>,</#sep>\r\n											</#list>\r\n										],\r\n									</#if>\r\n									\"regex\": \"${(relabel.regex)!\'\'}\",\r\n									\"action\": \"${(relabel.action)!\'\'}\"\r\n								</#if>\r\n								<#if relabel.action?? && relabel.action == \'replace\'>\r\n									<#if relabel.source_labels??&& (relabel.source_labels?size >0)>\r\n										\"source_labels\":[\r\n											<#list relabel.source_labels as label>\r\n												\"${label!\'\'}\"<#sep>,</#sep>\r\n											</#list>\r\n										],\r\n									</#if>\r\n									\"separator\": \";\",\r\n									\"regex\": \"${(relabel.regex)!\'\'}\",\r\n									\"replacement\": \"${(relabel.replacement)!\'\'}\",\r\n									\"action\": \"${(relabel.action)!\'\'}\",\r\n									\"target_label\": \"${(relabel.target_label)!\'\'}\"\r\n								</#if>\r\n							}\r\n						</#list>\r\n					</#if>\r\n				]\r\n			}\r\n			<#sep>,</#sep>\r\n		</#list>\r\n	\r\n	]\r\n	\r\n	<#-- cortex 处理 -->\r\n	,\r\n	\"remote_write\": [\r\n		<#list remoteWriteUrlInfos as remoteConf>\r\n		{	\r\n			\"url\": \"${remoteConf.url}\",\r\n			\"authorization\": {\r\n				\"type\": \"Bearer\",\r\n				\"credentials\": \"${remoteConf.token}\"\r\n			},\r\n			\"tls_config\":{\r\n				\"insecure_skip_verify\":true\r\n			},\r\n			\"queue_config\":{\r\n				\"capacity\": 5000,\r\n			    \"max_samples_per_send\": 1000,\r\n				\"min_shards\": 5,\r\n				\"max_shards\": 10,\r\n				\"min_backoff\": \"20ms\",\r\n				\"min_backoff\": \"50ms\"\r\n			}\r\n		}\r\n		<#sep>,</#sep>\r\n		</#list>\r\n	]	\r\n	</#if>\r\n}', 1, 'prometheus config文件模板');
REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (NULL, 'promtail_yml_tmpl', '{\r\n  \"server\": {\r\n    \"http_listen_address\": \"0.0.0.0\",\r\n    \"http_listen_port\": 19080,\r\n	\"grpc_listen_port\": 19081\r\n  },\r\n  \"clients\": [\r\n	<#list clientsMapList as clientMap>\r\n	{\r\n		\"url\" : \"${clientMap.url}\",\r\n		\"bearer_token\": \"${clientMap.token}\",\r\n		\"tls_config\":{\r\n			\"insecure_skip_verify\":true\r\n		}\r\n	}\r\n	<#sep>,</#sep>\r\n	</#list>\r\n  ],\r\n  \"positions\": {\r\n    \"filename\": \"/opt/nezha/promtail/positions.yaml\"\r\n  },\r\n  \"scrape_configs\": [\r\n  		<#list endpointList as endpoint>\r\n			{\r\n			\"job_name\": \"${endpoint.id?c}_${endpoint_index}\",\r\n			\"pipeline_stages\": [\r\n					<#if endpoint.config.pipeline??&&(endpoint.config.pipeline?size>0)>\r\n						<#list endpoint.config.pipeline as pipeline>\r\n						{\r\n						    <#if pipeline.type  == \"regex\">\r\n							\"regex\": {\r\n								\"expression\": \"${pipeline.expression}\",\r\n								\"source\": \"${pipeline.source}\"\r\n							}\r\n							</#if>\r\n							<#if pipeline.type  == \"json\">\r\n							\"json\": {\r\n							    \"expressions\": {\r\n									<#if pipeline.expressions??&& (pipeline.expressions?size >0)>\r\n									<#list pipeline.expressions?keys as key>\r\n										\"${key}\":\"${pipeline.expressions[key]}\"\r\n										<#sep>,</#sep>\r\n									</#list>\r\n								</#if>\r\n								},\r\n								\"source\": \"${pipeline.source}\"\r\n							}\r\n							</#if>\r\n							<#if pipeline.type  == \"template\">\r\n							 \"template\": {\r\n								\"source\": \"${pipeline.source}\",\r\n								\"template\": \"${pipeline.template}\"\r\n							}\r\n							</#if>\r\n							<#if pipeline.type  == \"timestamp\">\r\n							\"timestamp\": {\r\n								\"source\": \"${pipeline.source}\",\r\n								\"format\": \"${pipeline.format}\"\r\n							}\r\n                            </#if>\r\n							<#if pipeline.type  == \"labels\">	\r\n							\"labels\": {							\r\n								<#if pipeline.labels??&& (pipeline.labels?size >0)>\r\n									<#list pipeline.labels?keys as key>\r\n										\"${key}\":\"${pipeline.labels[key]}\"\r\n										<#sep>,</#sep>\r\n									</#list>\r\n								</#if>\r\n							}\r\n                            </#if>		\r\n							<#if pipeline.type  == \"output\">	\r\n							\"output\": {\r\n								\"source\": \"${pipeline.source}\"\r\n							}\r\n                            </#if>									\r\n						}\r\n						<#sep>,</#sep>\r\n						</#list>\r\n					</#if>\r\n			],\r\n			<#if endpoint.config.type  == \"file\">\r\n				\"static_configs\": [\r\n				{\r\n					\"labels\": {\r\n						\"__path__\": \"${endpoint.config.fileName}\",\r\n						\"datacenter\": 	\"${endpoint.dc.name}\",\r\n						\r\n						\"project\": 		\"${endpoint.project.name}\",\r\n						\r\n						\"asset\": 		\"${endpoint.asset.name}\",\r\n						\r\n						\"module\": 		\"${endpoint.module.name}\",\r\n						\r\n						\"endpoint\":     \"${endpoint.name}\",\r\n						\r\n						<#if endpoint.asset.parent??&&(endpoint.asset.parent?size >0)>\r\n							\"parent_asset\"      :  \"${endpoint.asset.parent.name}\"\r\n						</#if>\r\n						\r\n						<#if endpoint.config.labels??&& (endpoint.config.labels?size >0)>\r\n							,\r\n						</#if>\r\n						<#-- 补充用户自定义 Labels -->\r\n						<#if endpoint.config.labels??&& (endpoint.config.labels?size >0)>\r\n							<#list endpoint.config.labels?keys as key>\r\n								<#if key != \"datacenter\"  && key != \"project\" && key != \"asset\" && key != \"module\" && key != \"endpoint\">\r\n									\"${key}\":\"${endpoint.config.labels[key]}\"<#sep>,</#sep>\r\n								</#if>\r\n							 </#list>\r\n						</#if>\r\n\r\n					}\r\n				}\r\n			  ]\r\n			<#elseif endpoint.config.type == \"syslog\">\r\n				\"syslog\": {\r\n					\"listen_address\": \"${endpoint.config.listenAddress}\",\r\n					\"labels\": {\r\n					   \"datacenter\": 	\"${endpoint.dc.name}\",\r\n						\r\n						\"project\": 		\"${endpoint.project.name}\",\r\n						\r\n						\"asset\": 		\"${endpoint.asset.name}\",\r\n						\r\n						\"module\": 		\"${endpoint.module.name}\",\r\n						\r\n						\"endpoint\":     \"${endpoint.name}\",\r\n						\r\n						<#if endpoint.asset.parent??&&(endpoint.asset.parent?size >0)>\r\n							\"parent_asset\"      :  \"${endpoint.asset.parent.name}\"\r\n						</#if>\r\n						\r\n						<#if endpoint.config.labels??&& (endpoint.config.labels?size >0)>\r\n							,\r\n						</#if>\r\n						<#-- 补充用户自定义 Labels -->\r\n						<#if endpoint.config.labels??&& (endpoint.config.labels?size >0)>\r\n							<#list endpoint.config.labels?keys as key>\r\n								<#if key != \"datacenter\"  && key != \"project\" && key != \"asset\" && key != \"module\" && key != \"endpoint\">\r\n									\"${key}\":\"${endpoint.config.labels[key]}\"<#sep>,</#sep>\r\n								</#if>\r\n							 </#list>\r\n						</#if>\r\n			\r\n					}\r\n				},\r\n				\"relabel_configs\": [\r\n					{\r\n					  \"source_labels\": [\r\n						\"__syslog_message_app_name\"\r\n					  ],\r\n					  \"regex\":\"${endpoint.config.appName}\",\r\n					  \"action\":\"keep\"\r\n					},\r\n					{\r\n					  \"source_labels\": [\r\n						\"__syslog_message_app_name\"\r\n					  ],\r\n					  \"target_label\": \"appName\"\r\n					}\r\n				]	\r\n			<#elseif endpoint.config.type == \"journal\">\r\n				\"journal\": {\r\n					\"labels\": {\r\n						\"datacenter\": 	\"${endpoint.dc.name}\",\r\n						\r\n						\"project\": 		\"${endpoint.project.name}\",\r\n						\r\n						\"asset\": 		\"${endpoint.asset.name}\",\r\n						\r\n						\"module\": 		\"${endpoint.module.name}\",\r\n						\r\n						\"endpoint\":     \"${endpoint.name}\",\r\n						\r\n						<#if endpoint.asset.parent??&&(endpoint.asset.parent?size >0)>\r\n							\"parent_asset\"      :  \"${endpoint.asset.parent.name}\"\r\n						</#if>\r\n						\r\n						<#if endpoint.config.labels??&& (endpoint.config.labels?size >0)>\r\n							,\r\n						</#if>\r\n						<#-- 补充用户自定义 Labels -->\r\n						<#if endpoint.config.labels??&& (endpoint.config.labels?size >0)>\r\n							<#list endpoint.config.labels?keys as key>\r\n								<#if key != \"datacenter\"  && key != \"project\" && key != \"asset\" && key != \"module\" && key != \"endpoint\">\r\n									\"${key}\":\"${endpoint.config.labels[key]}\"<#sep>,</#sep>\r\n								</#if>\r\n							 </#list>\r\n						</#if>\r\n\r\n					}\r\n				},\r\n				\"relabel_configs\": [\r\n					{\r\n					  \"source_labels\": [\r\n						\"__journal__systemd_unit\"\r\n					  ],\r\n					  \"regex\":\"${endpoint.config.unit}\",\r\n					  \"action\":\"keep\"\r\n					},\r\n					{\r\n					  \"source_labels\": [\r\n						\"__journal__systemd_unit\"\r\n					  ],\r\n					  \"target_label\": \"unit\"\r\n					}\r\n				]	\r\n			</#if>\r\n			}\r\n		<#sep>,</#sep>\r\n		</#list>\r\n  ]\r\n}', 1, 'promtail.yml 配置模板');
REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (NULL, 'system_version', '21.10', 1, 'nezha系统版本');
REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (null, 'alert_export_header', '{\"zh\":{\"ID\":\"ID\",\"告警名称\":\"告警名称\",\"数据中心\":\"数据中心\",\"应用名称\":\"应用名称\",\"组件名称\":\"组件名称\",\"Endpoint\":\"Endpoint\",\"主机地址\":\"主机地址\",\"告警tag信息\":\"告警tag信息\",\"告警级别\":\"告警级别\",\"告警摘要\":\"告警摘要\",\"告警描述\":\"告警描述\",\"开始时间\":\"开始时间\",\"结束时间\":\"结束时间\",\"状态\":\"状态\"},\"en\":{\"ID\":\"ID\",\"Alert Name\":\"Alert Name\",\"Datacenter\":\"Datacenter\",\"Project\":\"Project\",\"Module\":\"Module\",\"Endpoint\":\"Endpoint\",\"Asset\":\"Asset\",\"Labels\":\"Labels\",\"Severity\":\"Severity\",\"Summary\":\"Summary\",\"Description\":\"Description\",\"StartAt\":\"StartAt\",\"EndAt\":\"EndAt\",\"State\":\"State\"}}', 1, 'alert_message导出表头');
REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (null, 'asset_export_header', '{\"zh\":{\"*SN码\":\"资产序列号，唯一标识(必填) \\n示例: A0420200101\",\"*资产类型\":\"设备类型（必填） \\n示例: server\",\"*厂商\":\"厂商（必填） \\n示例: Cisco\",\"*型号\":\"型号(必填) \\n示例: CISCO-UCS-C220\",\"*数据中心\":\"数据中心(必填) \\n示例: 北京电信中心机房\",\"机柜\":\"机柜 \\n示例: cabinet-001\",\"开始U位\":\"机柜开始位置 此信息一般和机柜结束位置联合使用 \\n示例: 1\",\"结束U位\":\"机柜结束位置 此信息一般与机柜开始位置联合使用 \\n示例: 2\",\"*主机地址\":\"主机地址(必填),IP格式 \\n示例: 172.0.0.1\",\"状态\":\"资产状态，可选: 在库、出库、停用 \\n示例: 在库\",\"购买日期\":\"购买日期 \\n示例: 2020/2/25\",\"SSH账号端口\":\"SSH连接端口 \\n示例: 22\",\"SSH账号登录名\":\"SSH账号登录名 \\n示例: root\",\"SSH登录认证方式\":\"SSH登录认证方式 密码登录:password,密钥登录:key \\n示例: password\",\"SSH登录密码\":\"SSH登录密码 认证方式为password时登录密码 \\n示例: xxxxx\",\"SSH登录密钥\":\"SSH登录密钥 \\n示例: ssh-rsa CFdv7Jez6K...\",\"SSH密钥密码\":\"SSH密钥密码 \\n示例: xxxxx\",\"TELNET账号端口\":\"TELNET账号端口 \\n示例: 23\",\"TELNET账号登录名\":\"TELNET账号登录名 \\n示例: root\",\"TELNET用户名提示\":\"TELNET用户名提示 \\n示例: user\",\"TELNET登录密码\":\"TELNET登录密码 \\n示例: xxxxx\",\"TELNET密码提示\":\"TELNET密码提示 \\n示例: pass\",\"TELNET重启密码提示\":\"TELNET重启密码提示 \\n示例: pass\",\"SNMP账号端口\":\"SNMP账号端口 \\n示例: 161\",\"SNMP团体名\":\"SNMP团体名 \\n示例: public\",\"SNMP上下文名称\":\"SNMP上下文名称 \\n示例: 80002b8046h\",\"SNMP协议版本\":\"SNMP协议版本 支持V2和V3 \\n示例: 2\",\"SNMP用户名\":\"SNMPV3版本时,登录用户名 \\n示例: root\",\"SNMP安全级别\":\"SNMP安全级别 noAuthNoPriv(不认证不加密) authNoPriv(认证不加密) authPriv(认证且加密) \\n示例: noAuthNoPriv\",\"SNMP用户密码\":\"SNMP用户密码, 根据安全级别选择填写 \\n示例: xxxxx\",\"SNMP认证协议\":\"SNMP用户认证协议 MD5、SHA \\n示例: MD5\",\"SNMP加密协议\":\"SNMP加密协议 AES、DES \\n示例: AES\",\"SNMP加密密码\":\"SNMP加密密码 \\n示例: xxxxx\",\"资产标签\":\"资产标签,tag信息,格式: key=value 如需填写多个请使用回车换行 \\n示例: isOpen=true \\n isHighPerformance=true\",\"Exporter\":\"是否安装内置node_exporter，1：安装，0：不安装 \\n示例：1\"},\"en\":{\"*Sn\":\"Asset serial number, unique identifier (required) \\nExample: A0420200101\",\"*Type\":\"Asset type (required) \\nExample: server\",\"*Vendor\":\"Vendor (required) \\nExample: Cisco\",\"*Model\":\"Model (required) \\nExample: CISCO-UCS-C220\",\"*IDC\":\"Data Center (Required) \\nExample: Beijing Telecom Center Computer Room\",\"Cabinet\":\"Cabinet \\nExample: cabinet-001\",\"Cabinet Start\":\"Cabinet start position This information is generally used in conjunction with the cabinet end position \\nExample: 1\",\"Cabinet End\":\"Cabinet end position This information is generally used in conjunction with the cabinet start position \\nExample: 2\",\"*Host\":\"Host address (required), IP format \\nExample: 172.0.0.1\",\"State\":\"Asset status, optional: In stock, Not in stock or Suspended \\nExample: In stock\",\"PurchaseDate\":\"Purchase date \\nExample: 2020/2/25\",\"SSH Account Port\":\"SSH account connection port \\nExample: 22\",\"SSH UserName\":\"SSH account login name \\nExample: root\",\"Methed\":\"SSH login authentication method, Password login: password, key login: key \\nExample: password\",\"SSH Password\":\"SSH login password The login password when the authentication method is password \\nExample: xxxxx\",\"PrivateKey\":\"SSH login key file \\nExample: ssh-rsa CFdv7Jez6K...\",\"Key Password\":\"SSH key password \\nExample: xxxxx\",\"TELNET Port\":\"TELNET account port \\nExample: 23\",\"TELNET Username\":\"TELNET account login name \\nExample: root\",\"User Tip\":\"TELNET username prompt \\nExample: user\",\"TELNET Password\":\"TELNET login password \\nExample: xxxxx\",\"Password Tip\":\"TELNET password prompt \\nExample: pass\",\"Relogin Tip\":\"TELNET relogin password prompt \\nExample: pass\",\"SNMP port\":\"SNMP account port \\nExample: 161\",\"Community\":\"SNMP community name \\nExample: public\",\"Context Name\":\"SNMP context name \\nExample: 80002b8046h\",\"Version\":\"SNMP protocol version supports V2 and V3 \\nExample: 2\",\"SNMP User\":\"In SNMPV3 version, login user name\\nExample: root\",\"SecurityLevel\":\"SNMP security level noAuthNoPriv (no authentication and no encryption) authNoPriv (authentication and no encryption) authPriv (authentication and encryption) \\nExample: noAuthNoPriv\",\"SNMP Password\":\"SNMP user password, fill in according to the security level \\nExample: xxxxx\",\"Auth Protocol\":\"SNMP auth protocol MD5, SHA \\nExample: MD5\",\"Priv Protocol\":\"SNMP priv protocol AES, DES \\nExample: AES\",\"Priv Password\":\"SNMP priv password \\nExample: xxxxx\",\"Tags\":\"Asset tag information, format: key=value If you need to fill in more than one, please use carriage return and line feed \\nExample: isOpen=true \\n isHighPerformance=true\",\"Exporter\":\"Whether to install the built-in node_exporter, 1: install, 0: not install \\nExample: 1\"}}', 1, 'asset导出表头');
REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (null, 'model_chart_export_header', '{\"zh\":{\"*图表名称\":\"图表名称(必填)支持{{asset.sn}},{{asset.host}},{{asset.tag.[key]}},{{asset.tag.key}}取值替换 \\n示例: CPU使用率\",\"*图表类型\":\"图表类型(必填) 可选: 曲线图,柱状图,表格,堆叠区域图,SingleStat,URL,告警列表,文本 \\n示例: 曲线图\",\"*宽度\":\"宽度(必填) 可选：1-12 \\n示例: 10\",\"*高度\":\"高度(必填),默认单位（px/像素） \\n示例:400\",\"单位\":\"单位(必填) 可选: \\nMisc: none,short,percent(0-100),percent(0.0-1.0),local format\\nData: bits,bytes,kilobytes,megabytes,gigabytes,terabytes,petabytes\\nDataRate: packets/sec,bits/sec,bytes/sec,kilobytes/sec,kilobits/sec,megabytes/sec,megabits/sec,gigabytes/sec,gigabits/sec,terabytes/sec,terabits/sec,petabytes/sec,petabits/sec\\nTime: Hertz(1/s),nanoseconds(ns),microseconds(us),milliseconds(ms),seconds(s),minutes(m),hours(h),days(d),YYYY-MM-DD HH:mm:ss,MM/DD/YYYY h:mm:ss a \\n示例: short\",\"*参数\":\"单位 根据type不同，内容不同，格式为JSON格式 ,支持{{asset.sn}},{{asset.host}},{{asset.tag.[key]}},{{asset.tag.key}}取值替换  \\n示例: {\\\"statistics\\\":\\\"average\\\"}\",\"元素\":\"当type=line，bar，stackArea时，包含 elements key，值为对象数组，其中 expression 支持{{asset.sn}},{{asset.host}},{{asset.tag.[key]}},{{asset.tag.key}}取值替换 \\n 示例:[{\\\"expression\\\":\\\"sum(up)\\\",\\\"legend\\\":\\\"test\\\"}]\"},\"en\":{\"*Chart Title\":\"Chart title(Required) Support {{asset.sn}},{{asset.host}},{{asset.tag.[key]}},{{asset.tag.key}} value replacement \\nExample: CPU usage\",\"*Chart Type\":\"Chart type(Required) Optional: Line Chart,Histogram,Table,Stack Area,SingleStat,URL,Alert list,Text \\nExample: Line Chart\",\"*Width\":\"width(Required) Optional：1-12 \\nExample: 10\",\"*Height\":\"height(Required),Default unit（px/Pixel） \\nExample:400\",\"Unit\":\"unit(Required) Optional: \\nMisc: none,short,percent(0-100),percent(0.0-1.0),local format\\nData: bits,bytes,kilobytes,megabytes,gigabytes,terabytes,petabytes\\nDataRate: packets/sec,bits/sec,bytes/sec,kilobytes/sec,kilobits/sec,megabytes/sec,megabits/sec,gigabytes/sec,gigabits/sec,terabytes/sec,terabits/sec,petabytes/sec,petabits/sec\\nTime: Hertz(1/s),nanoseconds(ns),microseconds(us),milliseconds(ms),seconds(s),minutes(m),hours(h),days(d),YYYY-MM-DD HH:mm:ss,MM/DD/YYYY h:mm:ss a \\nExample: short\",\"*Parameter\":\"Parameters match type，The format is JSON format,Support {{asset.sn}},{{asset.host}},{{asset.tag.[key]}},{{asset.tag.key}} value replacement \\nExample: {\\\"statistics\\\":\\\"average\\\"}\",\"Elements\":\"When the type is line, table, stackArea, singleStat, histogram, it contains elements key and the value is an object array.The expression support {{asset.sn}},{{asset.host}},{{asset.tag.[key]}},{{asset.tag.key}} value replacement \\nExample:[{\\\"expression\\\":\\\"sum(up)\\\",\\\"legend\\\":\\\"test\\\"}]\"}}', 1, NULL);
REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (null, 'endpoint_export_header', '{\"zh\":{\"*系统\":\"系统名称(必填) \\n示例: Nezha\",\"*组件\":\"组件名称(必填) \\n示例: node_exporter\",\"*组件类型\":\"组件类型(必填) 可选: HTTP、SNMP 当type = SNMP时，组件必须存在 \\n示例: HTTP\",\"资产序列号\":\"资产序列号(非必填) 与 主机地址 不能同时为空 \\n示例: A0420200101\",\"端口号\":\"端口号 范围0-65535 \\n示例: 9100\",\"参数\":\"端点查询参数，JSON格式， \\n示例: {\\\"key\\\":\\\"value\\\"}\",\"标签\":\"标签，JSON格式， \\n示例: {\\\"key\\\":\\\"value\\\"}\",\"*路径\":\"路径（必填） 请求路径，\\n示例: /metrics\",\"主机地址\":\"主机地址（非必填） 与 资产序列号 不能同时为空 \\n示例: 127.0.0.1\",\"启用\":\"启用状态（非必填） 可选 0:停用 1:启用,为空时默认为1 \\n示例: 1\"},\"en\":{\"*Project Name\":\"Project Name(Required) \\nExample: Nezha\",\"*Module Name\":\"Module Name(Required) \\nExample: node_exporter\",\"*Module Type\":\"Module type(Required) Optional: HTTP or SNMP，When type = SNMP, the component must exist \\nExample: HTTP\",\"Sn\":\"Asset serial number(Not required) And host address cannot be empty at the same time \\nExample: A0420200101\",\"Port\":\"Port number range 0-65535 \\nExample: 9100\",\"Parameter\":\"Endpoint query parameters, JSON format  \\nExample: {\\\"key\\\":\\\"value\\\"}\",\"Labels\":\"Endpoint lebel, JSON format  \\nExample: {\\\"key\\\":\\\"value\\\"}\",\"*Path\":\"Path (required) Request path \\nExample: /metrics\",\"Host\":\"Host address (not required) and asset serial number cannot be empty at the same time \\nExample: 127.0.0.1\",\"Enabled\":\"Enable state (not required) Optional values 0: Disable 1: Enable, when empty, the default is 1 \\nExample: 1\"}}', 1, NULL);
REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (null, 'expretmpl_export_header', '{\"zh\":{\"*名称\":\"模板名称(必填) \\n示例: CPU利用率模板\",\"组名\":\"组名 \\n示例: base，默认值: default\",\"*表达式\":\"表达式内容(必填) \\n示例: node_cpu_usage(asset=\\\"{{asset.host}}\\\",device=\\\"{{device}}\\\")\",\"描述\":\"描述 \\n示例: node_export CPU利用率模板\"},\"en\":{\"*Name\":\"Template name (required) \\nExample: CPU utilization template\",\"Group Name\":\"Group Name \\nExample: base, Default value: default\",\"*Expression\":\"Expression content (required) Optional: node_cpu_usage(asset=\\\"{{asset.host}}\\\",device=\\\"{{device}}\\\")\",\"Remark\":\"Remark \\nExample: node_export CPU utilization template\"}}', 1, '表达式导入导出模板表头信息');
REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (null, 'dc_export_header', '{\"zh\":{\"*名称\":\"名称（必填）\\n示例：xxx 数据中心\",\"位置\":\"位置 \\n示例：你的城市\",\"电话\":\"电话 \\n示例：9684631\",\"负责人\":\"机房负责人 \\n示例：admin\",\"经度\":\"经度 (-180,180) \\n示例：80\",\"纬度\":\"纬度 (-90,90) \\n示例：80\",\"*状态\":\"状态(必填) 可选：ON/OFF \\n示例：ON\"},\"en\":{\"*Name\":\"Name(Required) \\nExample: xxx datacenter\",\"Location\":\"Location \\nExample: your city\",\"Telephone\":\"Telephone \\nExample: 9684631\",\"Principal\":\"Principal \\nExample: admin\",\"Longitude\":\"Longitude (-180,180) \\nExample: 80\",\"Latitude\":\"Latitude (-90,90) \\nExample: 80\",\"*State\":\"State(Required) Optional: ON/OFF \\nExample: ON\"}}', 1, 'dc 导入导出表头信息');
REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (null, 'model_export_header', '{\"zh\":{\"*名称\":\"名称（必填）\\n示例：DELL-D3\",\"*品牌\":\"品牌（必填）\\n示例：DELL\",\"图表\":\"Asset 类型的图表模板 \\n示例：服务器模板,基本模板\",\"描述\":\"描述 \\n示例：DELL-D3\"},\"en\":{\"*Name\":\"Name(Required) \\nExample: DELL-D3\",\"*Brand\":\"Brand(Required) \\nExample: DELL\",\"Chart templates\":\"Asset chart templates  \\nExample: Server Template,Basic Template\",\"Description\":\"Description \\nExample: This is dell-d3\"}}', 1, 'asset model 导入导出表头信息');
REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (null, 'cabinet_export_header', '{\"zh\":{\"*名称\":\"名称（必填）\\n示例：机柜 1-1\",\"*数据中心\":\"数据中心（必填） \\n示例：xxx数据中心\",\"U位\":\"U位 \\n示例：10\",\"所在行\":\"所在行 \\n示例：1\",\"所在列\":\"所在列 \\n示例：1\",\"描述\":\"描述 \\n示例：2011年入库\"},\"en\":{\"*Name\":\"Name(Required) \\nExample: Cabinet 1-1\",\"*Data center\":\"Data center(Required) \\nExample: xxx data center\",\"U size\":\"U size (1,47)\\nExample: 10\",\"Row\":\"Row of data center \\nExample: 1\",\"Column\":\"Column of data center \\nExample: 1\",\"Description\":\"Description  \\nExample: In 2011\"}}', 1, 'cabinet 导入导出表头信息');
REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (null, 'module_export_header', '{\"zh\":{\"*名称\":\"名称（必填）\\n示例：Basic\",\"*系统\":\"系统名称（必填）\\n示例：System\",\"Endpoint名称模板\":\"Endpoint名称模板 默认 {{asse.host}}-{{module.name}} \\n示例：{{asse.host}}-{{module.name}}\",\"配置\":\"配置信息 JSON 格式 \\n示例：\\\"[{\\\"type\\\":\\\"metrics\\\",\\\"config\\\":{\\\"protocol\\\":\\\"SNMP\\\",\\\"walk\\\":[\\\"1.3.6.1.2.1.1\\\"],\\\"snmpCredentialsId\\\":1,\\\"host\\\":\\\"{{asset.manageIp}}\\\"},\\\"enable\\\":1},{\\\"type\\\":\\\"logs\\\",\\\"enable\\\":1}]\\\"\",\"图表\":\"Endpoint 类型的图表模板 \\n示例：服务器模板,基本模板\",\"描述\":\"描述 \\n示例：Basic\"},\"en\":{\"*Name\":\"Name(Required) \\nExample: Basic\",\"*Project\":\"Project name(Required) \\nExample: System\",\"Endpoint name template\":\"Endpoint name template Default {{asse.host}}-{{module.name}} \\nExample: {{asse.host}}-{{module.name}}\",\"Config\":\"Configuration information JSON format\\nExample:\\\"[{\\\"type\\\":\\\"metrics\\\",\\\"config\\\":{\\\"protocol\\\":\\\"SNMP\\\",\\\" walk\\\":[\\\"1.3.6.1.2.1.1\\\"],\\\"snmpCredentialsId\\\":1,\\\"host\\\":\\\"{{asset.manageIp}}\\\"},\\\"enable\\\" :1},{\\\"type\\\":\\\"logs\\\",\\\"enable\\\":1}]\\\"\",\"Chart templates\":\"Endpoint chart templates  \\nExample: Server Template,Basic Template\",\"Description\":\"Description \\nExample: This is basic module\"}}', 1, 'module 导入导出模板');
REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (null, 'monitor_endpoint_export_header', '{\"zh\":{\"*系统\":\"系统名称(必填) \\n示例: Nezha\",\"*组件\":\"组件名称(必填) \\n示例: node_exporter\",\"名称\":\"实例名称 \\n示例: node_exporter\",\"资产名称\":\"资产名称(非必填) 与 主机地址 不能同时为空 \\n示例: A0420200101\",\"配置\":\"实例配置，JSON格式， \\n示例: {\\\"key\\\":\\\"value\\\"}\"},\"en\":{\"*Project Name\":\"Project Name(Required) \\nExample: Nezha\",\"*Module Name\":\"Module Name(Required) \\nExample: node_exporter\",\"Name\":\"Endpoint name \\nExample: node_exporter\",\"Asset Name\":\"Asset name(Not required) And host address cannot be empty at the same time \\n示例: A0420200101\",\"Configs\":\"Endpoint Configs，JSON format， \\nExample: {\\\"key\\\":\\\"value\\\"}\"}}', 1, 'monitor endpoint 导入表头');
REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (null, 'asset_asset_export_header', '{\r\n    \"zh\": {\r\n        \"*资产名称\": \"资产名称，唯一标识(必填) \\n示例: DELL服务器\",\r\n        \"*SN码\": \"资产序列号，唯一标识(必填) \\n示例: A0420200101\",\r\n        \"虚拟机宿主\": \"虚拟机宿主，当资产为虚拟机时必填 \\n示例: DELL物理机\",\r\n        \"*管理ip\": \"主机地址(必填),IP格式 \\n示例: 172.0.0.1\",\r\n        \"*品牌\": \"品牌(必填) \\n示例: DELL\",\r\n        \"*型号\": \"型号(必填) \\n示例: DELL-D3\",\r\n        \"*数据中心\": \"数据中心(必填) \\n示例: 北京电信中心机房\",\r\n        \"机柜\": \"机柜 \\n示例: cabinet-001\",\r\n        \"开始U位\": \"机柜开始位置 此信息一般和机柜结束位置联合使用 \\n示例: 1\",\r\n        \"结束U位\": \"机柜结束位置 此信息一般与机柜开始位置联合使用 \\n示例: 2\",\r\n        \"*资产状态\": \"资产状态 \\n示例: 在库\",\r\n        \"*资产类型\": \"资产类型 \\n示例: 服务器\",\r\n        \"购买日期\": \"购买日期 \\n示例: 2020/2/25\",\r\n        \"属性信息\": \"资产属性信息,格式: key=value 如需填写多个请使用回车换行 \\n示例: NetworkCard=eth0 \\n user=root\",\r\n        \"认证服务端口\": \"认证服务端口 \\n示例: 22\",\r\n        \"认证方式\": \"认证方式,可选值: 1:用户名密码; 2: 密钥 \\n示例: 1\",\r\n        \"用户名\": \"用户名, \\n示例:root\",\r\n        \"密码\": \"密码 ,认证方式为1，记录登录密码; 认证方式为2,记录密钥密码.  \\n示例: pass\",\r\n        \"密钥\": \"登录密钥 \\n示例: ssh-rsa CFdv7Jez6K...\",\r\n        \"用户名提示\": \"TELNET用户名提示 \\n示例: login:\",\r\n        \"密码提示\": \"TELNET密码提示 \\n示例: pass:\",\r\n        \"SNMP凭证\": \"snmp凭证名称 \\n实例: system-snmpv2\",\r\n        \"Talon用户名\": \"Talon用户名 为空时默认：nezha \\n示例: admin\",\r\n        \"Talon密码\": \"Talon密码 为空时默认：nezha \\n示例: yourpass\",\r\n		\"Talon令牌\":\"Talon连接令牌, talon 状态开启时必填 \\n示例: e415da63\",\r\n        \"Talon服务端口\": \"Talon服务端口 为空时默认：10092 \\n示例: 10092\",\r\n		\"Talon开启状态\":\"Talon开启状态 为空时默认为0， 1: 开启 0: 关闭 \\n示例: 1\"\r\n    },\r\n    \"en\": {\r\n        \"*Asset Name\": \"Asset name, unique identifier (required) \\nExample: DELL server\",\r\n        \"*Sn\": \"Asset serial number, unique identifier (required) \\nExample: A0420200101\",\r\n        \"*Virtual machine host\": \"Virtual machine host, required when the asset is a virtual machine \\nExample: DELL physical machine\",\r\n        \"*Management ip\": \"Host address (required), IP format \\nExample: 172.0.0.1\",\r\n        \"*Brand\": \"Brand (required) \\nExample: DELL\",\r\n        \"*Model\": \"Model (required) \\nExample: DELL-D3\",\r\n        \"*DC\": \"Data Center (Required) \\nExample: Beijing Telecom Center Computer Room\",\r\n        \"Cabinet\": \"Cabinet \\nExample: cabinet-001\",\r\n        \"Cabinet Start\": \"Cabinet start position This information is generally used in conjunction with the cabinet end position \\nExample: 1\",\r\n        \"Cabinet End\": \"Cabinet end position This information is generally used in conjunction with the cabinet start position \\nExample: 2\",\r\n        \"*Asset state\": \"Asset status \\nExample: In stock\",\r\n        \"*Asset type\": \"Asset Type\\nExample: Server\",\r\n        \"Purchase date\": \"Purchase date \\nExample: 2020/2/25\",\r\n        \"Field Information\": \"Asset field information, format: key=value If you need to fill in more than one, please use carriage return and line feed \\nExample: NetworkCard=eth0 \\n user=root\",\r\n        \"Server port\": \"Server port \\nExample: 22\",\r\n        \"Auth methed\": \"Auth methed,Optional values: 1: username and password; 2: key \\nExample: 1\",\r\n        \"User name\": \"User name, \\nExample:root\",\r\n        \"Password\": \"Password ,The auth method is 1, record the login password; the auth method is 2, record the key password.  \\nExample: pass\",\r\n        \"PrivateKey\": \"PrivateKey \\nExample: ssh-rsa CFdv7Jez6K...\",\r\n        \"User Tip\": \"TELNET username prompt \\nExample: login:\",\r\n        \"Password Tip\": \"TELNET password prompt \\nExample: pass:\",\r\n        \"SNMP credential\": \"SNMP credential name \\nExample: system-snmpv2\",\r\n        \"Talon username\": \"Default when Talon username is empty: nezha \\nExample: nezha\",\r\n        \"Talon password\": \"Default when Talon password is empty: nezha \\nExample: yourpass\",\r\n		\"Talon token\":\"Talon connection token, talon is required to open \\nExample: e415da63\",\r\n        \"Talon service port\": \"When the Talon service port is empty, the default: 10092 \\nExample: 10092\",\r\n		\"Talon open status\":\"Talon open status Default is 0, 1: Open 0: Close \\nExample: 1\"\r\n    }\r\n}', 1, 'asset 导入导出表头信息');
REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (null, 'i18n_mapping', '{\"chartType\":{\"en\":{\"line\":\"Line Chart\",\"bar\":\"Histogram\",\"table\":\"Table\",\"stackArea\":\"Stack Area\",\"singleStat\":\"SingleStat\",\"url\":\"URL\",\"alertList\":\"Alert list\",\"text\":\"Text\",\"group\":\"Group\",\"pie\":\"Pie\",\"diagram\":\"Diagram\",\"logs\":\"Logs\"},\"zh\":{\"line\":\"曲线图\",\"bar\":\"柱状图\",\"table\":\"表格\",\"stackArea\":\"堆叠区域图\",\"singleStat\":\"SingleStat\",\"url\":\"URL\",\"alertList\":\"告警列表\",\"text\":\"文本\",\"group\":\"图表组\",\"pie\":\"饼图\",\"diagram\":\"Diagram\",\"logs\":\"Logs\"}}}', 1, NULL);
REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (null, 'rule_export_header', '{\"zh\":{\"*告警规则名称\":\"告警规则名称(必填) \\n示例: cpuAlert\",\"*告警类型\":\"告警类型(必填) 可选:1: Metrics 2:Logs 3:SNMP TRAP \\n示例: 1\",\"执行周期\":\"执行周期 默认值:0，单位:s 不小于 15 当 < 15, 则为 Scrape interval \\n示例: 30\",\"超时时间\":\"执行周期超时时间 默认值:0，单位:s 不小于 15 当 < 15, 则为 Scrape timeout \\n示例: 30\",\"*运算表达式\":\"运算表达式(必填) \\n示例: 100-(avg(irate(node_cpu_seconds_total{mode=\'idle\'}[5m])) by(instance)* 100)\",\"*比较符号\":\"比较符号(必填) 可选: >,<,<=,>=,==,!= \\n示例: >\",\"*阈值\":\"阈值(必填) \\n示例: 10\",\"*单位\":\"单位(必填) 可选: \\nMisc: none,short,percent(0-100),percent(0.0-1.0),local format\\nData: bits,bytes,kilobytes,megabytes,gigabytes,terabytes,petabytes\\nDataRate: packets/sec,bits/sec,bytes/sec,kilobytes/sec,kilobits/sec,megabytes/sec,megabits/sec,gigabytes/sec,gigabits/sec,terabytes/sec,terabits/sec,petabytes/sec,petabits/sec\\nTime: Hertz(1/s),nanoseconds(ns),microseconds(us),milliseconds(ms),seconds(s),minutes(m),hours(h),days(d),YYYY-MM-DD HH:mm:ss,MM/DD/YYYY h:mm:ss a \\n示例: short\",\"*持续时间\":\"持续时间(必填),默认单位（秒） \\n示例:60\",\"*告警级别\":\"告警级别(必填) 可选 P1、P2、P3 \\n示例: P1\",\"*告警摘要\":\"告警摘要(必填) \\n示例: cpu告警\",\"告警详细描述\":\"告警详细描述 \\n示例: cpu使用率超过10%的告警规则\",\"告警通知人\":\"告警通知人，多个使用逗号分隔 \\n示例: admin / admin,root\",\"通知方式\":\"告警通知方式，告警通知人不为空时，必填.多个使用逗号分隔 \\n示例: email / email,telephone\",\"告警状态\":\"告警状态，默认开启 开启：1 关闭：0 \\n示例:1\",\"自动失效\":\"是否自动失效 默认开启 开启：1 关闭：0 \\n示例:1\",\"定时\":\"定时是否开启 默认：关闭  1：开启 0：关闭 \\n示例:1\",\"定时开启定义\":\"定时开启天（星期几）定时开启时必填, 默认：1,2,3,4,5,6,7,多个逗号分隔, 例：1,2,3 \\n示例: 1,2,3,4,6\",\"开始时间\":\"开始时间 定时开启时必填,默认：00:00 \\n示例: 06:30\",\"关闭时间\":\"关闭时间 定时开启时必填,默认：23:59 \\n示例: 20:30\",\"告警激活通知\":\"告警激活通知开关 默认：开启 1：开启  0：关闭 \\n示例:1\",\"告警失效通知\":\"告警失效通知开关 默认：开启 1：开启  0：关闭 \\n示例:1\",\"故障排查\":\"故障排查描述信息 \\n示例:排查日志信息....\"},\"en\":{\"*Alert name\":\"Alert rule name (required) \\nExample: cpuAlert\",\"*Alert type\":\"Alert type (required) option: 1: metrics 2: logs 3: SNMP TRAP \\nExample: 1\",\"Execution cycle\":\"Performance Cycle Default: 0, unit: S is not less than 15 When <15, Scrape Interval \\nExample: 30\",\"Timeout\":\"Perform cycle timeout time default value: 0, unit: S is not less than 15 When <15, SCRAPE TIMEOUT \\nExample: 30\",\"*Expr\":\"Operation expression (required) \\nExample: 100-(avg(irate(node_cpu_seconds_total{mode=\'idle\')[5m])) by(instance)* 100)\",\"*Operator\":\"Operation symbol (required) Optional: >,<,<=,>=,==,!= \\nExample:>\",\"*Threshold\":\"Threshold (required) \\nExample: 10\",\"*Unit\":\"Unit (required) Optional: \\nMisc: none,short,percent(0-100),percent(0.0-1.0),local format\\nData: bits,bytes,kilobytes,megabytes,gigabytes,terabytes,petabytes\\nDataRate: packets/sec,bits/sec,bytes/sec,kilobytes/sec,kilobits/sec,megabytes/sec,megabits/sec,gigabytes/sec,gigabits/sec,terabytes/sec,terabits/sec,petabytes/sec,petabits/sec\\nTime: Hertz(1/s),nanoseconds(ns),microseconds(us),milliseconds(ms),seconds(s),minutes(m),hours(h),days(d),YYYY-MM-DD HH:mm:ss,MM/DD/YYYY h:mm:ss a \\nExample:short\",\"*Last\":\"Last (required), the default unit (seconds) \\nExample: 60\",\"*Severity\":\"Alert severity (required) optional P1, P2, P3 \\nExample: P1\",\"*Summary\":\"Alert summary \\nExample: Cpu warning\",\"Description\":\"Alert description \\nExample: Alarm rule for cpu usage exceeding 10%\",\"Receiver\":\"Alert receiver, separated by commas \\nExample: admin / admin,root\",\"Notification method\":\"Alarm notification method. When the receiver is not empty, it is required. Multiple use commas to separate \\nExample: email / email,telephone\",\"State\":\"Alarm status, the default enablement: 1 Close: 0 \\nExample: 1\",\"Automatic expired\":\"Whether automatic expired defaults to turn on: 1 Turn off: 0 \\nExample: 1\",\"Schedule\":\"schedule to turn on the default: Close 1: Open 0: Close \\nExample: 1\",\"Schedule days config\":\"schedule open day (week) Timer is turned on, default: 1,2,3,4,5,6,7 multiple comma separation \\nExample: 1,2,3,4,6\",\"Schedule start time\":\"Schedule start time is required when schedule is open, Default: 00:00 \\nExample: 06:30\",\"Schedule close time\":\"Schedule close time is required when schedule is open, default: 23: 59 \\nExample: 20:30\",\"Alarm activate notification\":\"Alarm activate notification switch Default: Open 1: Open 0: Close \\nExample: 1\",\"Alarm expired notification\":\"Alarm expired notification Switch Default: Open 1: Open 0: Close \\nExample: 1\",\"Trouble shooting\":\"Trouble shooting Description Information \\nExample: Check Log Information ....\"}}', 1, NULL);
