REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (null, 'asset_chart_export_header', '{\"zh\":{\"图表组名\":\"组名 \\n示例: default\",\"*图表名称\":\"图表名称(必填) \\n示例: CPU使用率\",\"*图表类型\":\"图表类型(必填) 可选: 曲线图,柱状图,表格,堆叠区域图,SingleStat,URL,告警列表,文本,图表组,Diagram,Logs \\n示例: 曲线图\",\"变量类型\":\"变量类型 当类型是 template 时必填，可选:Asset,Endpoint \\n示例: Asset\",\"*宽度\":\"宽度(必填) 可选：1-12 \\n示例: 10\",\"*高度\":\"高度(必填),可选：1-12 \\n示例: 10\",\"单位\":\"单位(必填) 可选: \\nMisc: none,short,percent(0-100),percent(0.0-1.0),local format\\nData: bits,bytes,kilobytes,megabytes,gigabytes,terabytes,petabytes\\nDataRate: packets/sec,bits/sec,bytes/sec,kilobytes/sec,kilobits/sec,megabytes/sec,megabits/sec,gigabytes/sec,gigabits/sec,terabytes/sec,terabits/sec,petabytes/sec,petabits/sec\\nTime: Hertz(1/s),nanoseconds(ns),microseconds(us),milliseconds(ms),seconds(s),minutes(m),hours(h),days(d),YYYY-MM-DD HH:mm:ss,MM/DD/YYYY h:mm:ss a \\n示例: short\",\"*参数\":\"单位 根据type不同，内容不同，格式为JSON格式 \\n示例: {\\\"statistics\\\":\\\"average\\\"}\",\"元素\":\"当type=line，bar，stackArea时，包含 elements key，值为对象数组。\\n 示例:[{\\\"expression\\\":\\\"sum(up)\\\",\\\"legend\\\":\\\"test\\\"}]\",\"描述\":\"当前图表描述说明\"},\"en\":{\"Chart Group\":\"Group name \\nExample: default\",\"*Chart Title\":\"Chart title(Required) \\nExample: CPU usage\",\"*Chart Type\":\"Chart type(Required) Optional: Line Chart,Histogram,Table,Stack Area,SingleStat,URL,Alert list,Text,Group,Diagram,Logs \\nExample: Line Chart\",\"Variable type\":\"Variable type Required when type is template, optional: Asset, Endpoint \\nExample: Asset\",\"*Width\":\"width(Required) Optional：1-12 \\nExample: 10\",\"*Height\":\"height(Required),Optional：1-12 \\nExample: 10\",\"Unit\":\"unit(Required) Optional: \\nMisc: none,short,percent(0-100),percent(0.0-1.0),local format\\nData: bits,bytes,kilobytes,megabytes,gigabytes,terabytes,petabytes\\nDataRate: packets/sec,bits/sec,bytes/sec,kilobytes/sec,kilobits/sec,megabytes/sec,megabits/sec,gigabytes/sec,gigabits/sec,terabytes/sec,terabits/sec,petabytes/sec,petabits/sec\\nTime: Hertz(1/s),nanoseconds(ns),microseconds(us),milliseconds(ms),seconds(s),minutes(m),hours(h),days(d),YYYY-MM-DD HH:mm:ss,MM/DD/YYYY h:mm:ss a \\nExample: short\",\"*Parameter\":\"Parameters match type，The format is JSON format \\nExample: {\\\"statistics\\\":\\\"average\\\"}\",\"Elements\":\"When the type is line, table, stackArea, singleStat, histogram, it contains elements key and the value is an object array.\\nExample:[{\\\"expression\\\":\\\"sum(up)\\\",\\\"legend\\\":\\\"test\\\"}]\",\"Description\":\"The chart description\"}}', 1, NULL);
REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (null, 'chart_export_header', '{\"zh\":{\"*面板\":\"面板名称(必填) \\n示例: 系统面板/主面板  （使用 / 作为字符分隔，表示 父子节点关系）\",\"图表组名\":\"组名 \\n示例: default\",\"*图表名称\":\"图表名称(必填) \\n示例: CPU使用率\",\"*图表类型\":\"图表类型(必填) 可选: 曲线图,柱状图,表格,堆叠区域图,SingleStat,URL,告警列表,文本,图表组,Diagram,Logs \\n示例: 曲线图\",\"*宽度\":\"宽度(必填) 可选：1-12 \\n示例: 10\",\"*高度\":\"高度(必填),可选：1-12 \\n示例: 10\",\"单位\":\"单位(必填) 可选: \\nMisc: none,short,percent(0-100),percent(0.0-1.0),local format\\nData: bits,bytes,kilobytes,megabytes,gigabytes,terabytes,petabytes\\nDataRate: packets/sec,bits/sec,bytes/sec,kilobytes/sec,kilobits/sec,megabytes/sec,megabits/sec,gigabytes/sec,gigabits/sec,terabytes/sec,terabits/sec,petabytes/sec,petabits/sec\\nTime: Hertz(1/s),nanoseconds(ns),microseconds(us),milliseconds(ms),seconds(s),minutes(m),hours(h),days(d),YYYY-MM-DD HH:mm:ss,MM/DD/YYYY h:mm:ss a \\n示例: short\",\"*参数\":\"单位 根据type不同，内容不同，格式为JSON格式 \\n示例: {\\\"statistics\\\":\\\"average\\\"}\",\"元素\":\"当type=line，bar，stackArea时，包含 elements key，值为对象数组。\\n 示例:[{\\\"expression\\\":\\\"sum(up)\\\",\\\"legend\\\":\\\"test\\\"}]\",\"描述\":\"当前图表的信息说明\"},\"en\":{\"*Panel Name\":\"Panel(Required) \\nExample: System panel/Main panel (use / as a character separation to indicate the relationship between parent and child nodes)\",\"Chart Group\":\"Group name \\nExample: default\",\"*Chart Title\":\"Chart title(Required) \\nExample: CPU usage\",\"*Chart Type\":\"Chart type(Required) Optional: Line Chart,Histogram,Table,Stack Area,SingleStat,URL,Alert list,Text,Group,Diagram,Logs \\nExample: Line Chart\",\"*Width\":\"width(Required) Optional：1-12 \\nExample: 10\",\"*Height\":\"height(Required) Optional：1-12 \\nExample: 10\",\"Unit\":\"unit(Required) Optional: \\nMisc: none,short,percent(0-100),percent(0.0-1.0),local format\\nData: bits,bytes,kilobytes,megabytes,gigabytes,terabytes,petabytes\\nDataRate: packets/sec,bits/sec,bytes/sec,kilobytes/sec,kilobits/sec,megabytes/sec,megabits/sec,gigabytes/sec,gigabits/sec,terabytes/sec,terabits/sec,petabytes/sec,petabits/sec\\nTime: Hertz(1/s),nanoseconds(ns),microseconds(us),milliseconds(ms),seconds(s),minutes(m),hours(h),days(d),YYYY-MM-DD HH:mm:ss,MM/DD/YYYY h:mm:ss a \\nExample: short\",\"*Parameter\":\"Parameters match type，The format is JSON format \\nExample: {\\\"statistics\\\":\\\"average\\\"}\",\"Elements\":\"When the type is line, table, stackArea, singleStat, histogram, it contains elements key and the value is an object array.\\nExample:[{\\\"expression\\\":\\\"sum(up)\\\",\\\"legend\\\":\\\"test\\\"}]\",\"Description\":\"The chart description\"}}', 1, NULL);
REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (NULL, 'system_version', '21.11', 1, 'nezha系统版本');
REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (NULL, 'prometheus_default_retention_time_when_s3', '1', 1, 'metrics 对象存储时普罗米修斯默认保留时间 单位: d');
REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (NULL, 'cortex_yml_tmpl', '{\r\n  \"auth_enabled\": false,\r\n  \"server\": {\r\n    \"http_listen_port\": <#if port?default(\"\")?trim?length gt 0> ${port?c} <#else>10093</#if>,\r\n	\"grpc_listen_port\":10094,\r\n    \"grpc_server_max_recv_msg_size\": 104857600,\r\n    \"grpc_server_max_send_msg_size\": 104857600,\r\n    \"grpc_server_max_concurrent_streams\": 1000\r\n  },\r\n  \"distributor\": {\r\n    \"shard_by_all_labels\": true,\r\n    \"pool\": {\r\n      \"health_check_ingesters\": true\r\n    }\r\n  },\r\n  \"ingester_client\": {\r\n    \"grpc_client_config\": {\r\n      \"max_recv_msg_size\": 104857600,\r\n      \"max_send_msg_size\": 104857600,\r\n      \"grpc_compression\": \"gzip\"\r\n    }\r\n  },\r\n  <#if isMemberlistStore && !isLocalStorage>\r\n	\"ingester\": {\r\n		\"lifecycler\": {\r\n		  \"join_after\": \"10s\",\r\n		  \"min_ready_duration\": \"0s\",\r\n		  \"final_sleep\": \"5s\",\r\n		  \"num_tokens\": 512,\r\n		  \"ring\": {\r\n			\"kvstore\": {\r\n			  \"store\": \"memberlist\"\r\n			},\r\n			\"replication_factor\": 1\r\n		  }\r\n		}\r\n	  },\r\n	  \"memberlist\": {\r\n		\"bind_port\": <#if gossIp?default(\"\")?trim?length gt 0>${gossIp?c}<#else>7946</#if>,\r\n		\"join_members\": [\r\n			<#list joinMemberList as joinIp>\r\n				\"${joinIp}:<#if gossIp?default(\"\")?trim?length gt 0>${gossIp?c}<#else>7946</#if>\"\r\n			<#sep>,</#sep>\r\n			</#list>\r\n		],\r\n		\"abort_if_cluster_join_fails\": false\r\n	  },\r\n  <#else>\r\n	  \"ingester\": {\r\n			\"lifecycler\": {\r\n			  \"join_after\": \"10s\",\r\n			  \"min_ready_duration\": \"0s\",\r\n			  \"final_sleep\": \"5s\",\r\n			  \"num_tokens\": 512,\r\n			  \"ring\": {\r\n				\"kvstore\": {\r\n				  \"store\": \"inmemory\"\r\n				},\r\n				\"replication_factor\": 1\r\n			  }\r\n			}\r\n		  },\r\n  </#if>\r\n  \r\n  \"storage\": {\r\n    \"engine\": \"blocks\"\r\n  },\r\n  \"blocks_storage\": {\r\n    \"tsdb\": {\r\n      \"dir\": \"${systemConfig.metrics_storage_local_path}/tsdb\"\r\n    },\r\n    \"bucket_store\": {\r\n      \"sync_dir\": \"${systemConfig.metrics_storage_local_path}/tsdb-sync\"\r\n    },\r\n	<#if isLocalStorage>\r\n		\"backend\": \"filesystem\",\r\n		\"filesystem\": {\r\n		  \"dir\": \"${systemConfig.metrics_storage_local_path}/data/tsdb\"\r\n		}\r\n	<#else>\r\n		\"backend\": \"s3\",\r\n		\"s3\": {\r\n		  \"endpoint\": \"${objectStroageUrl}\",\r\n		  \"bucket_name\": \"${bucketName}\",\r\n		  \"access_key_id\": \"${accessKey}\",\r\n		  \"secret_access_key\": \"${secret}\",\r\n		  \"insecure\": <#if insecure?default(\"\")?trim?length gt 0>${insecure}<#else>true</#if>\r\n		}\r\n	</#if>\r\n  },\r\n  \"store_gateway\": {\r\n    \"sharding_enabled\": true,\r\n    \"sharding_ring\": {\r\n      \"kvstore\": {\r\n        \"store\": <#if isMemberlistStore && !isLocalStorage> \"memberlist\" <#else> \"inmemory\" </#if>\r\n      }\r\n    }\r\n  },\r\n  \"compactor\": {\r\n    \"data_dir\": \"${systemConfig.metrics_storage_local_path}/compactor\",\r\n    \"sharding_ring\": {\r\n      \"kvstore\": {\r\n        \"store\": <#if isMemberlistStore && !isLocalStorage> \"memberlist\" <#else> \"inmemory\" </#if>\r\n      }\r\n    }\r\n  },\r\n  \"frontend_worker\": {\r\n    \"match_max_concurrent\": true\r\n  },\r\n  \r\n  <#if isAlert>\r\n	  \"ruler\": {\r\n		\"enable_api\": true,\r\n		\"enable_sharding\": true,\r\n		\"rule_path\": \"${systemConfig.metrics_storage_local_path}/rules\",\r\n		\"ring\": {\r\n		  \"num_tokens\": 512,\r\n		  \"kvstore\": {\r\n			\"store\": <#if isMemberlistStore && !isLocalStorage> \"memberlist\" <#else> \"inmemory\" </#if>\r\n		  }\r\n		},\r\n		\"alertmanager_url\":\"${systemConfig.alert_api}${systemConfig.alert_path_prefix}\"\r\n	  },\r\n	  \"ruler_storage\":{\r\n		 \"backend\":\"local\",\r\n		 \"local\":{\r\n		   \"directory\":\"${systemConfig.metrics_storage_local_path}/rules\"\r\n		 }\r\n	  },\r\n  </#if>\r\n  \"limits\":{\r\n	\"max_series_per_metric\": 500000000,\r\n	\"ingestion_rate\": 500000000\r\n  },\r\n  \"api\":{\r\n     \"alertmanager_http_prefix\":\"/\"\r\n  },\r\n  \"table_manager\":{\r\n	  \"retention_deletes_enabled\": true,\r\n	  \"retention_period\": \"${(((systemConfig.metrics_storage_retention!30)?number)*24)?c}h\"\r\n	}\r\n}', 1, 'cortex.yml 配置文件模板');
REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (NULL, 'loki_yml_tmpl', '{\r\n	\"auth_enabled\": false,\r\n	\"server\": {\r\n		\"http_listen_port\": <#if httpPort?default(\"\")?trim?length gt 0> ${httpPort?c} <#else>13100</#if>\r\n	},\r\n    \"ingester\": {\r\n		\"lifecycler\": {\r\n			\"ring\": {\r\n				\"kvstore\": {\r\n					\"store\": \"inmemory\"\r\n				},\r\n				\"replication_factor\": 1\r\n			},\r\n			\"final_sleep\": \"0s\",\r\n			\"join_after\":\"30s\"\r\n		},\r\n    \"chunk_idle_period\": \"5m\",\r\n    \"chunk_retain_period\": \"30s\"\r\n   },\r\n   \"schema_config\": {\r\n		\"configs\": [\r\n			{\r\n				\"from\": \"${schemaConfigFrom}\",\r\n			<#if openAws>\r\n				\"store\": \"boltdb-shipper\",\r\n				\"object_store\": \"aws\",\r\n				\"schema\": \"v11\",\r\n				\"index\": {\r\n					\"prefix\": \"index_\",\r\n					\"period\": \"24h\"\r\n				}\r\n			<#else> \r\n				\"store\": \"boltdb\",\r\n				\"object_store\": \"filesystem\",\r\n				\"schema\": \"v11\",\r\n				\"index\": {\r\n				  \"prefix\": \"index_\",\r\n				  \"period\": \"168h\"\r\n				}\r\n			</#if>\r\n			}\r\n		]\r\n	},\r\n<#if openAws>\r\n	\"compactor\": {\r\n		\"working_directory\": \"/loki/compactor\",\r\n		\"shared_store\": \"aws\"\r\n	},\r\n	\"storage_config\": {\r\n		\"boltdb_shipper\": {\r\n			\"shared_store\": \"aws\",\r\n			\"active_index_directory\": \"/loki/index\",\r\n			\"cache_location\": \"/loki/boltdb-cache\"\r\n		},\r\n		\"aws\": {\r\n			\"s3\": \"s3://${accessKey}:${secret}@${objectStroageUrl}/${bucketName}\",\r\n			\"s3forcepathstyle\": true,\r\n			\"insecure\": <#if insecure?default(\"\")?trim?length gt 0>${insecure}<#else>false</#if>\r\n		}\r\n	}\r\n<#else> \r\n	\"storage_config\": {\r\n		\"boltdb\": {\r\n			\"directory\": \"${storageLocalPath}/index\"\r\n		},\r\n		\"filesystem\": {\r\n			\"directory\": \"${storageLocalPath}/chunks\"\r\n		}\r\n	},\r\n	\"limits_config\": {\r\n		\"enforce_metric_name\": false,\r\n		\"reject_old_samples\": true,\r\n		\"reject_old_samples_max_age\": \"${storageRetention}h\",\r\n		\"ingestion_rate_mb\": 15\r\n	},\r\n	\"chunk_store_config\": {\r\n		\"max_look_back_period\": \"2160h\"\r\n	}\r\n</#if>\r\n	,\"table_manager\":{\r\n		\"retention_deletes_enabled\": true,\r\n		\"retention_period\": \"${(((((systemConfig.logs_storage_retention!7)?number)/7)?ceiling)*7*24)?c}h\"\r\n	}\r\n}', 1, 'loki.yml 配置文件模板');
